CREATE TABLE system_control(id boolean PRIMARY KEY DEFAULT true CHECK(id),environment_id uuid NOT NULL,instance_id uuid NOT NULL DEFAULT gen_random_uuid(),run_id uuid NOT NULL DEFAULT gen_random_uuid(),dispatch_epoch bigint NOT NULL DEFAULT 1,restore_hold boolean NOT NULL DEFAULT true,clock_at timestamptz NOT NULL DEFAULT now(),provider_checked_at timestamptz,worker_at timestamptz,provider_instance_id uuid,provider_cursor bigint NOT NULL DEFAULT 0,unfinished_jobs bigint NOT NULL DEFAULT 0,unpublished_events bigint NOT NULL DEFAULT 0,CHECK(unfinished_jobs>=0),CHECK(unpublished_events>=0));
CREATE TABLE operation(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,actor_id uuid NOT NULL,kind varchar(40) NOT NULL,resource_id uuid NOT NULL,action_key varchar(128) NOT NULL,fingerprint char(64) NOT NULL,provider_key varchar(128) NOT NULL UNIQUE,schema_version int NOT NULL DEFAULT 1,policy_version varchar(30) NOT NULL DEFAULT 'mprp_v1',payload text NOT NULL,status varchar(20) NOT NULL CHECK(status IN('QUEUED','DISPATCHING','UNKNOWN','SUCCEEDED','FAILED','CANCELLED')),safe_result text,reason text,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(merchant_id,actor_id,kind,resource_id,action_key));
CREATE TABLE durable_job(id uuid PRIMARY KEY,operation_id uuid UNIQUE REFERENCES operation(id),kind varchar(40) NOT NULL,resource_id uuid NOT NULL,merchant_id uuid,state varchar(20) NOT NULL DEFAULT 'READY',owner uuid,generation bigint NOT NULL DEFAULT 0,lease_until timestamptz,run_id uuid,dispatch_epoch bigint,due_at timestamptz NOT NULL DEFAULT now(),attempts int NOT NULL DEFAULT 0,last_error varchar(200),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX job_due ON durable_job(state,due_at);
CREATE TABLE stream_head(stream text NOT NULL,aggregate_id uuid NOT NULL,sequence bigint NOT NULL,PRIMARY KEY(stream,aggregate_id));
CREATE TABLE publication_outbox(id uuid PRIMARY KEY,merchant_id uuid,aggregate_id uuid NOT NULL,stream varchar(40) NOT NULL,sequence bigint NOT NULL,envelope text NOT NULL,digest char(64) NOT NULL,owner uuid,generation bigint NOT NULL DEFAULT 0,lease_until timestamptz,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(stream,aggregate_id,sequence));
CREATE INDEX outbox_pending ON publication_outbox(stream,aggregate_id,sequence) WHERE published_at IS NULL;
CREATE TABLE consumer_receipt(consumer varchar(100) NOT NULL,event_id uuid NOT NULL,digest char(64) NOT NULL,disposition varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(consumer,event_id));
CREATE TABLE consumer_stream(consumer varchar(100) NOT NULL,stream text NOT NULL,aggregate_id uuid NOT NULL,sequence bigint NOT NULL,PRIMARY KEY(consumer,stream,aggregate_id));
CREATE TABLE deferred_event(consumer text NOT NULL,event_id uuid NOT NULL,envelope text NOT NULL,PRIMARY KEY(consumer,event_id));
CREATE TABLE callback_nonce(key_id text NOT NULL,nonce text NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(key_id,nonce));
CREATE TABLE callback_inbox(id uuid PRIMARY KEY,digest char(64) NOT NULL,payload text NOT NULL,state varchar(20) NOT NULL DEFAULT 'ACCEPTED',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quarantine(id uuid PRIMARY KEY,kind text NOT NULL,digest text NOT NULL,safe_reason varchar(300) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_head(stream text PRIMARY KEY,sequence bigint NOT NULL,digest char(64) NOT NULL);
CREATE TABLE audit_event(id uuid PRIMARY KEY,stream text NOT NULL,sequence bigint NOT NULL,merchant_id uuid,actor_id uuid,action varchar(100) NOT NULL,resource_id uuid,reason varchar(2000) NOT NULL,previous_hash char(64) NOT NULL,digest char(64) NOT NULL,canonical text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(stream,sequence));
CREATE TABLE notification(id uuid PRIMARY KEY,user_id uuid NOT NULL,merchant_id uuid,title varchar(200) NOT NULL,body varchar(2000) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE report_export(id uuid PRIMARY KEY,user_id uuid NOT NULL,merchant_id uuid,kind varchar(40) NOT NULL,status varchar(20) NOT NULL DEFAULT 'QUEUED',cutoff timestamptz NOT NULL DEFAULT now(),content bytea,digest char(64),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recovery_inventory(id uuid PRIMARY KEY,maker_id uuid NOT NULL,checker_id uuid,fingerprint char(64) NOT NULL,content text NOT NULL,status varchar(20) NOT NULL DEFAULT 'PROPOSED',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable financial history' USING ERRCODE='23514'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_event FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER receipt_immutable BEFORE UPDATE OR DELETE ON consumer_receipt FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE FUNCTION operation_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.merchant_id,NEW.actor_id,NEW.kind,NEW.resource_id,NEW.action_key,NEW.fingerprint,NEW.provider_key,NEW.payload,NEW.policy_version,NEW.schema_version) IS DISTINCT FROM (OLD.merchant_id,OLD.actor_id,OLD.kind,OLD.resource_id,OLD.action_key,OLD.fingerprint,OLD.provider_key,OLD.payload,OLD.policy_version,OLD.schema_version) THEN RAISE EXCEPTION 'Immutable operation identity'; END IF; RETURN NEW; END $$;
CREATE TRIGGER operation_identity BEFORE UPDATE ON operation FOR EACH ROW EXECUTE FUNCTION operation_identity_guard();
